function o(e,{isFree:t=!1}={}){if(t)return"Free";if(e==null||e==="")return"Negotiable";const n=Number(e);return Number.isNaN(n)?"Negotiable":n===0?"Free":`৳ ${n.toLocaleString("en-IN")}`}function u(e){if(!e)return"";const t=new Date(e);return Number.isNaN(t.getTime())?"":t.toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"numeric"})}function f(e){if(!e)return"";const t=new Date(e);if(Number.isNaN(t.getTime()))return"";const n=Math.floor((Date.now()-t.getTime())/1e3);if(n<60)return"just now";const i=[["year",31536e3],["month",2592e3],["week",604800],["day",86400],["hour",3600],["minute",60]];for(const[r,s]of i){const a=Math.floor(n/s);if(a>=1)return`${a} ${r}${a!==1?"s":""} ago`}return"just now"}function c(e){if(!e)return"";const t=String(e).replace(/\D/g,""),n=t.startsWith("880")?`0${t.slice(3)}`:t;return n.length<4?"XXXXX-XXXXXX":`${n.slice(0,3)}XX-XXXXXX`}function l(e){if(!e)return"Bangladesh";const t=e.area||e.area_name,n=e.district||e.district_name,i=e.division||e.division_name,r=[t,n||i].filter(Boolean);return r.length?r.join(", "):e.full_address||"Bangladesh"}function m(e=""){return e.split(" ").filter(Boolean).slice(0,2).map(t=>t[0].toUpperCase()).join("")||"?"}function X(e=""){return e.replace(/_/g," ").replace(/\b\w/g,t=>t.toUpperCase())}export{o as a,l as b,f as c,u as f,X as h,m as i,c as m};
